// Max-specific language layer. Shared animation principles reuse the Blender lab's translations.
import { STAGES } from './stages.js';

const stepText = (stage, step, field) => field.startsWith('how')
  ? STAGES[stage].steps[step].how[Number(field.slice(3))]
  : STAGES[stage].steps[step][field];
const step = (stage, number, field, ca, es) => [stepText(stage, number, field), { ca, es }];
